/**
 * @param {number} radius
 * @param {number} xCenter
 * @param {number} yCenter
 * @param {number} x1
 * @param {number} y1
 * @param {number} x2
 * @param {number} y2
 * @return {boolean}
 */
var checkOverlap = function(radius, xCenter, yCenter, x1, y1, x2, y2) {
    let squareX = Math.min(Math.max(x1, xCenter), x2);
    let squareY = Math.min(Math.max(y1, yCenter), y2);

    const xDiff = squareX - xCenter;
    const yDiff = squareY - yCenter;

    return (xDiff ** 2) + (yDiff ** 2) <= (radius ** 2);
};
